import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/zx.html","title":"zx","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.62,"words":186},"filePathRelative":"zx.md"}`),a={name:`zx.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="zx" tabindex="-1"><a class="header-anchor" href="#zx"><span>zx</span></a></h1><p><a href="./技術的なメモ.html">技術的なメモ</a>, <a href="./Shell.html">Shell</a>, <a href="./JavaScript.html">JavaScript</a></p><ul><li><a href="https://github.com/google/zx" target="_blank" rel="noopener noreferrer">google/zx: A tool for writing better scripts</a></li><li><a href="https://google.github.io/zx/getting-started" target="_blank" rel="noopener noreferrer">Getting Started - google/zx</a> ドキュメント</li><li><a href="https://github.com/dsherret/dax" target="_blank" rel="noopener noreferrer">dax: Cross-platform shell tools for Deno and Node.js inspired by zx.</a> 競合 <ul><li><a href="https://matklad.github.io/2026/01/27/make-ts.html" target="_blank" rel="noopener noreferrer">make.ts</a>より</li></ul></li></ul><p><a href="./JavaScript.html">JavaScript</a>でシェルっぽく雑用するためのライブラリ。 <a href="./OilShell.html">OilShell</a>のアップデートで学び直さないといけない事が結構あってうんざりしてきたので、zxへの乗り換えを検討してみる。</p><h2 id="文字列とprocess-output" tabindex="-1"><a class="header-anchor" href="#文字列とprocess-output"><span>文字列とprocess output</span></a></h2><p>ちょっと引っかかりやすいのが、プロセスの結果は文字列では無くProcessOutputというオブジェクトで来るが、 ドル記号で文字列に展開しているので普段は気にしなくていい、という所。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> path <span class="token operator">=</span> <span class="token keyword">await</span> $<span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">pwd</span><span class="token template-punctuation string">\`</span></span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>path<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token comment">// undeifined</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>path<span class="token punctuation">.</span><span class="token function">toString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>length<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ちなみにlinesで行配列としてとれる。</p><h2 id="tempfileと削除" tabindex="-1"><a class="header-anchor" href="#tempfileと削除"><span>tempfileと削除</span></a></h2><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> temp_cont <span class="token operator">=</span> <span class="token function">tmpfile</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">await</span> fs<span class="token punctuation">.</span><span class="token function">rm</span><span class="token punctuation">(</span>temp_cont<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="しばらく作業した雑感、結構いいね" tabindex="-1"><a class="header-anchor" href="#しばらく作業した雑感、結構いいね"><span>しばらく作業した雑感、結構いいね</span></a></h2><p><a href="./てきすとTL.html">てきすとTL</a>からTeFWikiにいろいろGUIを挟んでpublishするよなスクリプトを書いてみたが、なかなか良い。</p><p>まずnodeなので学習曲線が急で良い。</p><p>そしてそんなのnode素で書けばいいのでは？というのは、意外とそうでもない。 やはりプロセスとpipe周りが整備されているのは快適で良い。 だいぶシェルスクリプトっぽい感覚で外部コマンドを呼べる。mkdirのpオプションとか普通に使えるので良い。</p><p>そして追加で学習しないといけない事が少ないので、<a href="./OilShell.html">OilShell</a>よりもメンテナンス容易さも期待出来る。 nodeはそんなに大きくは変わらないので、スクリプトの大部分はそのまま使える事が期待出来る。</p><p>nodeはfs周りがかったるさがあるので、それがシェルコマンドで補えるのは結構いいね。</p><p>今後はちょっと凝ったシェルスクリプト的なものはこれでいこう、という気分になった。</p>`,17)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};